const q = $('Terima Pertanyaan').item.json.body || {};
const hari = $json.hari_data_terakhir;
return [{
  json: {
    merchant_id: q.merchant_id,
    question: q.question,
    hari_data_terakhir: hari,
  },
}];

// Jalur fallback: agent error atau output tidak valid sama sekali.
return [{
  json: {
    output: {
      jawaban: 'Asisten AI sedang tidak tersedia, pertanyaan diteruskan ke CS.',
      data_dipakai: [],
      confidence: 0,
      perlu_eskalasi: true,
    },
    _fallback: true,
  },
}];

// Titik gabung: dicapai dari Lolos Guardrail? (false) ATAU Fallback: AI Gagal.
// Jangan referensi node per-cabang di sini - keduanya sudah dinormalisasi jadi bentuk yang sama.
const out = $json.output || {};
const alasan = $json._fallback ? 'ai_error' : (out.perlu_eskalasi ? 'perlu_eskalasi' : 'confidence_rendah');
return [{
  json: {
    merchant_id: $('Siapkan Konteks').item.json.merchant_id,
    question: $('Siapkan Konteks').item.json.question,
    jawaban: out.jawaban || '',
    data_dipakai: out.data_dipakai || [],
    confidence: out.confidence != null ? out.confidence : 0,
    alasan,
  },
}];

